function offsets(B,e){for(const p of B.parts)p.group.position.copy(p.base).addScaledVector(p.offset,e);}
function finish(B,key,update){return {...B,info:EXTRA_INFO[key],update};}
function boltsCircle(B,g,r,z,n=8){B.bolts(g,Array.from({length:n},(_,i)=>[r*Math.cos(i*TAU/n),r*Math.sin(i*TAU/n),z]),'z',.065);}
