 const bearings=B.part('bearings','主轴承','BEARINGS','前后轴承支承中心旋转组件。',[1.8,0,1]);B.bearing(bearings,.48,[0,0,1.65],'z',outputRadius);B.bearing(bearings,.48,[0,0,-1],'z',inputRadius);
